456	interface TextSegment {
457	  text: string;
458	  /** Inside a fenced block: code, not prose. */
459	  code: boolean;
460	}
461	
462	/**
463	 * `text` in alternating runs of prose and fenced code, by CommonMark's rule:
464	 * a fence opens with at least three backticks or tildes (up to three spaces of
465	 * indent) and closes with the same character, at least as many of them, and
466	 * nothing else on the line. A fence never closed runs to the end of the text,
467	 * which is the safe direction -- the rest is evidence rather than bookkeeping.
468	 *
469	 * Backtick fences may not carry backticks in their info string; that rule is what
470	 * keeps an inline `` `a` `` inside a sentence from opening a block.
471	 */
472	function fenceSegments(text: string): TextSegment[] {
473	  const lines = text.match(/[^\n]*\n|[^\n]+$/g) ?? [];
474	  const segments: TextSegment[] = [];
475	  let open: { char: string; length: number } | null = null;
476	  let current: TextSegment = { text: "", code: false };
477	
478	  for (const line of lines) {
479	    const bare = line.replace(/\r?\n$/, "");
480	    const fence = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(bare);
481	    if (open === null) {
482	      const opens = fence !== null && (fence[1]![0] !== "`" || !fence[2]!.includes("`"));
483	      if (opens) {
484	        if (current.text) segments.push(current);
485	        open = { char: fence[1]![0]!, length: fence[1]!.length };
486	        current = { text: line, code: true };
487	      } else {
488	        current.text += line;
489	      }
490	      continue;
491	    }
492	
493	    current.text += line;
494	    if (fence && fence[1]![0] === open.char && fence[1]!.length >= open.length && fence[2]!.trim() === "") {
495	      segments.push(current);
496	      current = { text: "", code: false };
497	      open = null;
498	    }
499	  }
500	
501	  if (current.text) segments.push(current);
502	  return segments;
503	}

