2	/**
3	 * parse_comment_command.ts — Parse a GitHub comment and extract either a
4	 * slash-command agent name and optional session mode, or a control command, from
5	 * any line.
6	 *
7	 * Human commands must occupy their own line: `/engineer` or
8	 * `/engineer recover`. Instructions belong on following lines. Internal
9	 * dispatch comments remain accepted for automation.
10	 *
11	 * The syntax itself is `domain/work/comment-command.ts`, shared with the thread reader
12	 * and with the refusal that keeps an agent from writing a command into a body.
13	 *
14	 * Env: ATOMATON_COMMENT_BODY
15	 * Writes `parsed`, `matched`, `agent`, `control`, `session_mode`, and `error` to
16	 * $GITHUB_OUTPUT. `parsed` is `true` whenever this script ran -- a step that does not
17	 * run leaves every output empty, and a comment with no command in it writes
18	 * `matched=false`, so the guard cannot tell those apart without it.
19	 */
20	import { appendFileSync } from "node:fs";
21	import { proseOnly } from "../../adapters/github/tags.ts";
22	import { parseCommentCommand } from "../../domain/work/comment-command.ts";
23	import { defineScript } from "./lib/script-ref.ts";
24	
25	export const ref = defineScript(import.meta.url);
26	
27	function main(): void {
28	  // Read as prose (#311): a `/engineer` inside a fenced code block is somebody
29	  // quoting the command format, and the thread readers do not take it for a request
30	  // either. The entry and the thread must answer "is this a command" the same way,
31	  // or a run starts on an ask the thread cannot see.
32	  const body = proseOnly(process.env.ATOMATON_COMMENT_BODY ?? "");
33	  const { agent, control, sessionMode, error } = parseCommentCommand(body);
34	  const matched = agent ? "true" : "false";
35	
36	  const githubOutput = process.env.GITHUB_OUTPUT;
37	  if (githubOutput) {
38	    // `parsed` says this step RAN, which `matched` cannot: a step that does not run
39	    // leaves every output empty, and so does a comment with no command in it. The
40	    // guard's commands rule turns on the difference -- a comment from somebody who is
41	    // not a repository member is never read here, so it must not be refused for what it
42	    // would have asked for (#217).
43	    appendFileSync(githubOutput, `parsed=true\n`);
44	    appendFileSync(githubOutput, `matched=${matched}\nagent=${agent}\ncontrol=${control}\n`);
45	    appendFileSync(githubOutput, `session_mode=${sessionMode}\nerror=${error}\n`);
46	  }
